// The whole game. A seeded LCG turns the seed into a secret in 1..100.
function secretFor(seed) {
  let s = (Number(seed) * 2654435761) >>> 0;
  s = (1103515245 * s + 12345) >>> 0;
  return 1 + (s % 100);
}

const seed = nb.get('seed') ?? 7;
const secret = secretFor(seed);
const guess = nb.get('guess');
const tries = nb.get('tries') ?? 0;

if (guess == null) return 'Enter a guess above, press Submit, then run this cell.';

const diff = Number(guess) - secret;
let feedback;
if (diff === 0) {
  feedback = `🎉 Correct! ${secret} in ${tries} tries. Change the seed for a new game.`;
} else {
  const mag = Math.abs(diff);
  const temp = mag <= 2 ? '🔥 boiling' : mag <= 5 ? 'warm' : mag <= 15 ? 'cool' : '❄️ freezing';
  feedback = `${diff > 0 ? 'Too high' : 'Too low'} — ${temp}`;
}

console.log('guess', guess, '(' + typeof guess + '), tries', tries);
return { guess, tries, feedback };  // note: secret is only revealed on a win

// Live values — proof the controls bind the right types for the game logic.
const val = (k) => ({ value: nb.get(k), type: typeof nb.get(k) });
return {
  guess: val('guess'),  // number — number inputs never hand you a string
  tries: val('tries'),  // number — the increment button keeps a real counter
  seed:  val('seed'),   // number — feeds the deterministic secret
};
